const escapeRegex=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
export function emphasize(root,state){if(!root)return;const names=[...state.students.map(s=>s.name),state.config.teacherName,'윤서진','한정우','박수현','이은서','최하늘','김지완'].filter(s=>s.length>=2).sort((a,b)=>b.length-a.length);const namesSet=new Set(names);const re=new RegExp(names.map(escapeRegex).join('|')+'|(?:[01]?\\d|2[0-3]):[0-5]\\d|(?:오전|오후)? ?\\d{1,2}시(?: ?\\d{1,2}분)?','g');const doc=root.ownerDocument,walker=doc.createTreeWalker(root,4),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(!n.parentElement?.closest('script,style,textarea,select,option,input,.text-person,.text-time,.portrait')&&re.test(n.textContent))nodes.push(n);re.lastIndex=0;}
 for(const n of nodes){const fragment=doc.createDocumentFragment(),text=n.textContent;let start=0;for(const match of text.matchAll(re)){fragment.append(doc.createTextNode(text.slice(start,match.index)));const span=doc.createElement('span');span.className=namesSet.has(match[0])?'text-person':'text-time';span.textContent=match[0];fragment.append(span);start=match.index+match[0].length;}fragment.append(doc.createTextNode(text.slice(start)));n.replaceWith(fragment);}}
